CREATE TYPE "WorkOrderStatus" AS ENUM ('RECEIVED','DIAGNOSING','WAITING_PARTS','REPAIRING','READY','DELIVERED','CANCELLED');
ALTER TABLE "Workshop" ADD COLUMN "nextOrderNumber" INTEGER NOT NULL DEFAULT 1;
CREATE TABLE "Client" ("id" UUID NOT NULL,"workshopId" UUID NOT NULL,"firstName" VARCHAR(100) NOT NULL,"lastName" VARCHAR(100) NOT NULL,"phone" VARCHAR(40) NOT NULL,"email" VARCHAR(254),"address" VARCHAR(200) NOT NULL,"notes" VARCHAR(1000),"archivedAt" TIMESTAMPTZ(3),"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "Client_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Device" ("id" UUID NOT NULL,"workshopId" UUID NOT NULL,"clientId" UUID NOT NULL,"brand" VARCHAR(100) NOT NULL,"model" VARCHAR(100) NOT NULL,"serialNumber" VARCHAR(100),"color" VARCHAR(60),"physicalCondition" VARCHAR(1000) NOT NULL,"archivedAt" TIMESTAMPTZ(3),"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "Device_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WorkOrder" ("id" UUID NOT NULL,"workshopId" UUID NOT NULL,"deviceId" UUID NOT NULL,"orderNumber" INTEGER NOT NULL,"reportedIssue" VARCHAR(2000) NOT NULL,"diagnosis" VARCHAR(2000),"workPerformed" VARCHAR(2000),"status" "WorkOrderStatus" NOT NULL DEFAULT 'RECEIVED',"estimatedBudget" DECIMAL(12,2),"finalPrice" DECIMAL(12,2),"receivedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"estimatedAt" TIMESTAMPTZ(3),"deliveredAt" TIMESTAMPTZ(3),"notes" VARCHAR(2000),"archivedAt" TIMESTAMPTZ(3),"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "WorkOrder_pkey" PRIMARY KEY ("id"),CONSTRAINT "WorkOrder_estimatedBudget_check" CHECK ("estimatedBudget" >= 0),CONSTRAINT "WorkOrder_finalPrice_check" CHECK ("finalPrice" >= 0));
CREATE UNIQUE INDEX "Client_id_workshopId_key" ON "Client"("id","workshopId"); CREATE INDEX "Client_workshopId_archivedAt_createdAt_idx" ON "Client"("workshopId","archivedAt","createdAt");
CREATE UNIQUE INDEX "Device_id_workshopId_key" ON "Device"("id","workshopId"); CREATE INDEX "Device_workshopId_archivedAt_createdAt_idx" ON "Device"("workshopId","archivedAt","createdAt"); CREATE INDEX "Device_clientId_workshopId_idx" ON "Device"("clientId","workshopId");
CREATE UNIQUE INDEX "WorkOrder_workshopId_orderNumber_key" ON "WorkOrder"("workshopId","orderNumber"); CREATE INDEX "WorkOrder_workshopId_archivedAt_receivedAt_id_idx" ON "WorkOrder"("workshopId","archivedAt","receivedAt","id"); CREATE INDEX "WorkOrder_deviceId_workshopId_idx" ON "WorkOrder"("deviceId","workshopId"); CREATE INDEX "WorkOrder_workshopId_status_idx" ON "WorkOrder"("workshopId","status");
ALTER TABLE "Client" ADD CONSTRAINT "Client_workshopId_fkey" FOREIGN KEY ("workshopId") REFERENCES "Workshop"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Device" ADD CONSTRAINT "Device_workshopId_fkey" FOREIGN KEY ("workshopId") REFERENCES "Workshop"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Device" ADD CONSTRAINT "Device_clientId_workshopId_fkey" FOREIGN KEY ("clientId","workshopId") REFERENCES "Client"("id","workshopId") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "WorkOrder" ADD CONSTRAINT "WorkOrder_workshopId_fkey" FOREIGN KEY ("workshopId") REFERENCES "Workshop"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "WorkOrder" ADD CONSTRAINT "WorkOrder_deviceId_workshopId_fkey" FOREIGN KEY ("deviceId","workshopId") REFERENCES "Device"("id","workshopId") ON DELETE RESTRICT ON UPDATE CASCADE;
